import{_ as t,c as e,o as l,ae as o}from"./chunks/framework.BQlYxExx.js";const p=JSON.parse('{"title":"使用指南","description":"","frontmatter":{},"headers":[],"relativePath":"usage.md","filePath":"usage.md","lastUpdated":null}'),r={name:"usage.md"};function i(s,a,c,h,n,d){return l(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="使用指南" tabindex="-1">使用指南 <a class="header-anchor" href="#使用指南" aria-label="Permalink to &quot;使用指南&quot;">​</a></h1><h2 id="登录" tabindex="-1">登录 <a class="header-anchor" href="#登录" aria-label="Permalink to &quot;登录&quot;">​</a></h2><h3 id="河南师大智慧教务" tabindex="-1">河南师大智慧教务 <a class="header-anchor" href="#河南师大智慧教务" aria-label="Permalink to &quot;河南师大智慧教务&quot;">​</a></h3><p>主要用于获取教务相关数据，如课程表、成绩、教室等。</p><h4 id="微信登录-推荐" tabindex="-1">微信登录（推荐） <a class="header-anchor" href="#微信登录-推荐" aria-label="Permalink to &quot;微信登录（推荐）&quot;">​</a></h4><ol><li>关注微信公众号 <strong>河南师范大学智慧教务</strong>。</li><li>进入公众号后，点击菜单栏中的 <strong>教务系统</strong> 选项，进行登录。</li><li>登录成功后点击右上角三个点，使用 <strong>师韵</strong> 打开。</li><li>如果你在短时间内重复在微信公众号中登录，可能会导致登录失败，请稍等片刻后重试。</li></ol><h4 id="账号密码登录" tabindex="-1">账号密码登录 <a class="header-anchor" href="#账号密码登录" aria-label="Permalink to &quot;账号密码登录&quot;">​</a></h4><p>打开师韵后点击登录提示栏将跳转到登录页面。密码与<a href="http://jwc.htu.edu.cn" target="_blank" rel="noreferrer">网页版教务系统</a>一致。</p><h3 id="统一认证登录" tabindex="-1">统一认证登录 <a class="header-anchor" href="#统一认证登录" aria-label="Permalink to &quot;统一认证登录&quot;">​</a></h3><p>主要用于查看留言板、智慧学工、一网通办等。</p><p>当你需要登录时应用会自动弹出登录对话框。密码与校园网、i 师大一致。</p><h3 id="第二课堂" tabindex="-1">第二课堂 <a class="header-anchor" href="#第二课堂" aria-label="Permalink to &quot;第二课堂&quot;">​</a></h3><p>主要用于获取第二课堂相关数据，如活动、学时等。</p><h3 id="图书馆管理系统" tabindex="-1">图书馆管理系统 <a class="header-anchor" href="#图书馆管理系统" aria-label="Permalink to &quot;图书馆管理系统&quot;">​</a></h3><p>主要用于获取图书馆相关数据，如借阅信息等。</p><h2 id="安全性说明" tabindex="-1">安全性说明 <a class="header-anchor" href="#安全性说明" aria-label="Permalink to &quot;安全性说明&quot;">​</a></h2><p>师韵不会收集、存储或分享您的任何个人信息。所有数据均加密后安全地保存在本地。</p><h2 id="数据来源" tabindex="-1">数据来源 <a class="header-anchor" href="#数据来源" aria-label="Permalink to &quot;数据来源&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">新闻数据</p><ul><li>河南师范大学官网 <a href="https://www.htu.edu.cn" target="_blank" rel="noreferrer">https://www.htu.edu.cn</a> 及其相关站点</li></ul></div><div class="tip custom-block"><p class="custom-block-title">教务数据</p><ul><li>河南师大智慧教务 <a href="https://jwc.htu.edu.cn/app" target="_blank" rel="noreferrer">https://jwc.htu.edu.cn/app</a></li></ul></div><div class="tip custom-block"><p class="custom-block-title">第二课堂数据</p><ul><li>第二课堂管理系统 <a href="http://dekt.htu.edu.cn" target="_blank" rel="noreferrer">http://dekt.htu.edu.cn</a></li></ul></div><h2 id="功能介绍" tabindex="-1">功能介绍 <a class="header-anchor" href="#功能介绍" aria-label="Permalink to &quot;功能介绍&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">新闻阅览</p><p>即时获取校园最新资讯，紧跟校园动态。</p></div><div class="info custom-block"><p class="custom-block-title">今日课程</p><p>一键查看当日课程安排，助您轻松规划学习日程。</p></div><div class="info custom-block"><p class="custom-block-title">课程成绩</p><p>提供快速成绩查询服务，成绩变化一目了然，助您随时掌握学业进展。</p></div><div class="info custom-block"><p class="custom-block-title">教室查询</p><p>实时查询教室占用情况，助您合理规划学习时间，提升学习效率。</p></div><div class="info custom-block"><p class="custom-block-title">第二课堂</p><p>集中展示参与活动及学时统计，让您对课外活动了如指掌。</p></div><h1 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h1>',28)])])}const b=t(r,[["render",i]]);export{p as __pageData,b as default};
